import { Contact } from "@/store/contactSlice";

export default async function fetchServerPage(
  limit: number,
  offset: number = 0
): Promise<{ rows: Contact[]; nextOffset: number | undefined; hasMore: boolean }> {
  try {
    // Fetch contacts from your API with pagination
    const response = await fetch(`/api/contact?limit=${limit}&offset=${offset}`);
    
    if (!response.ok) {
      throw new Error("Failed to fetch contacts");
    }

    const data = await response.json();
    const contacts: Contact[] = data.contacts || [];
    const hasMore = contacts.length === limit;

    return {
      rows: contacts,
      nextOffset: hasMore ? offset + 1 : undefined,
      hasMore,
    };
  } catch (error) {
    console.error("Error fetching contacts:", error);
    return { rows: [], nextOffset: undefined, hasMore: false };
  }
}
