"use client";
import { useSocketConnection } from "./hooks/useSocketConnection";
import { NotificationHeader } from "./Components/NotificationHeader";
import { NotificationCard } from "../Components/NotificationCard";
import { EmptyState } from "../Components/EmptyState";
import { useRef } from "react";
import LoadingSpinner from "@/Components/LoadingSpinner";
import { useDispatch } from "react-redux";
import { markAsRead } from "@/store/contactSlice";
import { updateContactReadStatus } from "@/lib/updateContactStatus";

import {
  QueryClient,
  QueryClientProvider,
  useInfiniteQuery,
} from "@tanstack/react-query";

import { useVirtualizer } from "@tanstack/react-virtual";
import fetchServerPage from "./virtualization";

const queryClient = new QueryClient();

function ContactsContent() {
  const dispatch = useDispatch();
  
  const {
    status,
    data,
    error,
    isFetchingNextPage,
    fetchNextPage,
    hasNextPage,
  } = useInfiniteQuery({
    queryKey: ["contacts"],
    queryFn: (ctx) => fetchServerPage(20, ctx.pageParam),
    getNextPageParam: (lastGroup) => lastGroup.nextOffset,
    initialPageParam: 0,
  });

  const allRows = data ? data.pages.flatMap((d) => d.rows) : [];

  const { isConnected, showReconnectMessage, dismissReconnectMessage } =
    useSocketConnection();

  const handleMarkAsRead = async (id: string) => {
    dispatch(markAsRead(id));
    await updateContactReadStatus(id, true);
  };

  const parentRef = useRef<HTMLDivElement>(null);
  const rowVirtualizer = useVirtualizer({
    count: allRows.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 160,
    overscan: 5,
  });

  return (
    <QueryClientProvider client={queryClient}>
      <div className="space-y-6">
        <NotificationHeader
          isConnected={isConnected}
          showReconnectMessage={showReconnectMessage}
          onDismissReconnect={dismissReconnectMessage}
        />

        {/* Virtualized Notifications List */}
        <div
          ref={parentRef}
          className="relative h-[600px] overflow-auto rounded-xl border border-gray-800 bg-gray-900/60 shadow-lg"
        >
          <div
            style={{ height: rowVirtualizer.getTotalSize() }}
            className="relative w-full"
          >
            {rowVirtualizer.getVirtualItems().map((virtualRow) => {
              const notification = allRows[virtualRow.index];
              return (
                <div
                  key={notification.id || `notification-${virtualRow.index}`}
                  className="absolute left-0 w-full"
                  style={{
                    top: 0,
                    transform: `translateY(${virtualRow.start}px)`,
                    height: `${virtualRow.size}px`,
                  }}
                >
                  <NotificationCard
                    notification={notification}
                    onMarkAsRead={handleMarkAsRead}
                  />
                </div>
              );
            })}
          </div>
          {isFetchingNextPage && (
            <div className="absolute bottom-4 left-1/2 -translate-x-1/2">
              <LoadingSpinner />
            </div>
          )}
        </div>
        {hasNextPage && !isFetchingNextPage && (
          <button
            onClick={() => fetchNextPage()}
            className="mt-6 px-6 py-3 bg-blue-700 hover:bg-blue-800 text-white rounded-lg font-semibold shadow transition-colors duration-200"
          >
            Load More
          </button>
        )}
        {status === "loading" && (
          <div className="flex justify-center items-center py-12">
            <LoadingSpinner />
          </div>
        )}
        {error && (
          <div className="text-red-500 font-semibold py-4 text-center">
            Error loading notifications
          </div>
        )}
      </div>
    </QueryClientProvider>
  );
}
